  "updatedAt" text NOT NULL DEFAULT to_char(statement_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
  "_rowid" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
