  CONSTRAINT "scheduled_tasks_check_3" CHECK (("scheduleType" = 'recurring' AND ("cronExpression" IS NOT NULL OR "intervalMs" IS NOT NULL)) OR ("scheduleType" = 'one_time')),
  CONSTRAINT "scheduled_tasks_check_4" CHECK (("targetType" = 'agent-task' AND "taskTemplate" IS NOT NULL) OR ("targetType" = 'workflow' AND "workflowId" IS NOT NULL) OR ("targetType" = 'script' AND "scriptName" IS NOT NULL))
);

