  "startedAt" timestamptz(3),
  "finishedAt" timestamptz(3),
  "created_by" text,
  "updated_by" text,
  "_rowid" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "user_merge_jobs_check_1" CHECK ("status" IN ('pending', 'running', 'done', 'failed'))
);

CREATE TABLE "user_tokens" (
  "id" text,
  "userId" text NOT NULL,
  "label" text,
  "tokenHash" text NOT NULL,
  "tokenPreview" text NOT NULL,
  "createdAt" timestamptz(3) NOT NULL DEFAULT statement_timestamp(),
  "lastUsedAt" timestamptz(3),
  "revokedAt" timestamptz(3),
  "created_by" text,
  "updated_by" text,
  "expiresAt" timestamptz(3),
  "_rowid" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  PRIMARY KEY ("id"),
  UNIQUE ("tokenHash")
);

CREATE TABLE "users" (
  "id" text DEFAULT replace(gen_random_uuid()::text, '-', ''),
  "name" text NOT NULL,
  "email" text,
  "role" text,
  "notes" text,
  "emailAliases" jsonb DEFAULT '[]'::jsonb,
  "preferredChannel" text DEFAULT 'slack',
  "timezone" text,
  "metadata" jsonb,
  "dailyBudgetUsd" double precision,
  "status" text NOT NULL DEFAULT 'active',
  "createdAt" text NOT NULL DEFAULT to_char(statement_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  "lastUpdatedAt" text NOT NULL DEFAULT to_char(statement_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  "created_by" text,
  "updated_by" text,
  "mergedIntoUserId" text,
  "avatar" text,
  "_rowid" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "users_check_1" CHECK ("status" IN ('invited', 'active', 'suspended'))
);

CREATE TABLE "wait_states" (
  "id" text,
  "workflowRunId" text NOT NULL,
  "workflowRunStepId" text NOT NULL,
  "mode" text NOT NULL,
  "wakeUpAt" timestamptz(3),
  "eventName" text,
  "eventFilter" jsonb,
  "expiresAt" timestamptz(3),
  "status" text NOT NULL DEFAULT 'pending',
  "firedPayload" jsonb,
  "resolvedAt" timestamptz(3),
  "createdAt" timestamptz(3) DEFAULT statement_timestamp(),
  "updatedAt" timestamptz(3) DEFAULT statement_timestamp(),
  "eventScope" text NOT NULL DEFAULT 'run',
  "_rowid" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "wait_states_check_1" CHECK ("mode" IN ('time', 'event')),
  CONSTRAINT "wait_states_check_2" CHECK ("status" IN ('pending', 'fired', 'timeout')),
  CONSTRAINT "wait_states_check_3" CHECK ("eventScope" IN ('run', 'global'))
);

CREATE TABLE "workflow_idempotency_keys" (
  "id" text,
  "principal" text NOT NULL,
  "operation" text NOT NULL,
  "targetId" text NOT NULL DEFAULT '',
  "keyHash" text NOT NULL,
  "requestFingerprint" text NOT NULL,
  "workflowId" text NOT NULL,
  "runId" text,
  "responseStatus" bigint NOT NULL,
  "responseBody" text,
  "resourceDeletedAt" timestamptz(3),
  "createdAt" timestamptz(3) NOT NULL,
  "created_by" text,
  "updated_by" text,
  "_rowid" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "workflow_idempotency_keys_check_1" CHECK ("operation" IN ('workflow.create', 'workflow.trigger'))
);

CREATE TABLE "workflow_run_definitions" (
  "hash" text,
  "snapshot" text NOT NULL,
  "createdAt" timestamptz(3) NOT NULL,
  "_rowid" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  PRIMARY KEY ("hash")
);

CREATE TABLE "workflow_run_steps" (
  "id" text,
  "runId" text NOT NULL,
  "nodeId" text NOT NULL,
  "nodeType" text NOT NULL,
  "status" text NOT NULL DEFAULT 'running',
  "input" text,
  "output" text,
  "error" text,
  "startedAt" timestamptz(3) NOT NULL DEFAULT statement_timestamp(),
  "finishedAt" timestamptz(3),
  "retryCount" bigint NOT NULL DEFAULT 0,
  "maxRetries" bigint NOT NULL DEFAULT 0,
  "nextRetryAt" timestamptz(3),
  "idempotencyKey" text,
  "diagnostics" text,
  "nextPort" text,
  "created_by" text,
  "updated_by" text,
  "output_replay" text,
  "_rowid" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  PRIMARY KEY ("id"),
  UNIQUE ("idempotencyKey"),
  CONSTRAINT "workflow_run_steps_check_1" CHECK ("status" IN ('pending', 'running', 'waiting', 'completed', 'failed', 'skipped', 'cancelled'))
);

CREATE TABLE "workflow_runs" (
  "id" text,
  "workflowId" text NOT NULL,
  "status" text NOT NULL DEFAULT 'running',
  "triggerData" jsonb,
  "context" jsonb,
  "error" text,
  "startedAt" timestamptz(3) NOT NULL DEFAULT statement_timestamp(),
  "lastUpdatedAt" text NOT NULL DEFAULT to_char(statement_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  "finishedAt" timestamptz(3),
  "created_by" text,
  "updated_by" text,
  "triggerType" text NOT NULL DEFAULT 'manual',
  "context_replay" text,
  "parentStepId" text,
  "parentStepAttempt" bigint NOT NULL DEFAULT 0,
  "triggeredByAgentId" text,
  "definitionHash" text,
  "sourceStepId" text,
  "principal" text,
  "_rowid" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "workflow_runs_check_1" CHECK ("status" IN ('running', 'waiting', 'completed', 'failed', 'skipped', 'cancelled')),
  CONSTRAINT "workflow_runs_check_2" CHECK ("triggerType" IN ('schedule', 'manual', 'event', 'api'))
);

CREATE TABLE "workflow_versions" (
  "id" text,
  "workflowId" text NOT NULL,
  "version" bigint NOT NULL,
  "snapshot" jsonb NOT NULL,
  "changedByAgentId" text,
  "createdAt" text NOT NULL DEFAULT to_char(statement_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  "created_by" text,
