  "vcs_repo" text,
  "created_by" text,
  "updated_by" text,
  "key" text NOT NULL DEFAULT 'shared/',
  "params" jsonb NOT NULL DEFAULT '{}'::jsonb,
  "requiredParams" jsonb NOT NULL DEFAULT '[]'::jsonb,
  "requires" jsonb NOT NULL DEFAULT '[]'::jsonb,
  "updatedByAgentId" text,
  "_rowid" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  PRIMARY KEY ("id"),
  UNIQUE ("name")
);

